/**
 * ProfitMaps AI / GeoRank Pro - "Site Plan" Sitemap Architect
 * Path: /src/components/builder/SitePlanView.tsx
 *
 * Implements:
 * - State 1 (Empty): "Turn your keywords and rankings into a website plan" with stat cards and [ Create site plan ] CTA.
 * - State 2 (Generated Sitemap Tree):
 *   - Column 1: Main Pages (Home, Contact, About us, Common questions)
 *   - Column 2: Areas We Serve (Auto-generated from towns & neighborhoods)
 *   - Column 3: Services (Auto-generated from tracked keywords)
 *   - Action: [ Build this site → ] launching live builder preview.
 */

import React, { useState } from 'react';
import {
  Globe,
  Layers,
  MapPin,
  FileCode,
  Sparkles,
  ArrowRight,
  CheckCircle2,
  Building,
  Target,
  ExternalLink,
  Plus,
  RefreshCw,
  FolderTree,
} from 'lucide-react';

export interface SitePlanViewProps {
  businessName?: string;
  category?: string;
  city?: string;
  trackedKeywords?: string[];
  areasServedList?: string[];
  competitorCount?: number;
  onLaunchSiteBuilder?: (selectedSlug?: string) => void;
}

export const SitePlanView: React.FC<SitePlanViewProps> = ({
  businessName = 'Austin Premier Plumbing',
  category = 'Emergency Plumber',
  city = 'Austin, TX',
  trackedKeywords = ['Emergency Plumber', 'Water Heater Repair', '24/7 Drain Cleaning', 'Leak Detection'],
  areasServedList = ['Downtown Austin', 'South Congress', 'Barton Hills', 'Zilker', 'Tarrytown'],
  competitorCount = 3,
  onLaunchSiteBuilder,
}) => {
  const [isPlanGenerated, setIsPlanGenerated] = useState<boolean>(true); // Pre-generated by default or toggleable
  const [isGenerating, setIsGenerating] = useState<boolean>(false);

  const mainPages = [
    { title: 'Home', slug: '/', desc: 'Primary local authority hub with 3-pack proof' },
    { title: 'About Us', slug: '/about-us', desc: 'Team credentials, licensing & history' },
    { title: 'Contact & Dispatch', slug: '/contact', desc: 'Emergency click-to-call & booking form' },
    { title: 'Common Questions (FAQ)', slug: '/faq', desc: 'Local FAQ schema for Google AI Overviews' },
  ];

  const servicePages = trackedKeywords.map((kw) => ({
    title: kw,
    slug: `/${kw.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`,
    desc: `Dedicated landing page targeting high-intent '${kw}' queries`,
  }));

  const areaPages = areasServedList.map((area) => {
    const cleanArea = area.replace(/[^a-zA-Z0-9\s]/g, '').trim();
    return {
      title: `${category} in ${cleanArea}`,
      slug: `/${cleanArea.toLowerCase().replace(/\s+/g, '-')}-${category.toLowerCase().replace(/\s+/g, '-')}`,
      desc: `Hyper-local neighborhood coverage for ${cleanArea}`,
    };
  });

  const totalPages = mainPages.length + servicePages.length + areaPages.length;

  const handleGeneratePlan = () => {
    setIsGenerating(true);
    setTimeout(() => {
      setIsPlanGenerated(true);
      setIsGenerating(false);
    }, 800);
  };

  return (
    <div className="space-y-6">
      {/* State 1: Empty / Initial Prompt */}
      {!isPlanGenerated ? (
        <div className="bg-white p-10 rounded-2xl border border-slate-200 shadow-xs text-center space-y-6 max-w-2xl mx-auto my-6">
          <div className="w-16 h-16 bg-emerald-100 text-emerald-700 rounded-2xl mx-auto flex items-center justify-center shadow-xs">
            <FolderTree className="w-8 h-8" />
          </div>

          <div>
            <h2 className="text-xl font-bold text-slate-900">
              Turn your keywords and rankings into a website plan
            </h2>
            <p className="text-xs text-slate-500 mt-1.5 max-w-md mx-auto leading-relaxed">
              We'll automatically architecture every page Google needs to rank <strong className="text-slate-800">{businessName}</strong> across your target territory.
            </p>
          </div>

          {/* Stat Cards */}
          <div className="grid grid-cols-3 gap-3">
            <div className="bg-slate-50 p-3.5 rounded-xl border border-slate-200/80">
              <span className="text-xl font-black font-mono text-slate-900 block">
                {trackedKeywords.length}
              </span>
              <span className="text-[11px] font-semibold text-slate-500">Tracked Keywords</span>
            </div>
            <div className="bg-slate-50 p-3.5 rounded-xl border border-slate-200/80">
              <span className="text-xl font-black font-mono text-emerald-700 block">
                25 Pins
              </span>
              <span className="text-[11px] font-semibold text-slate-500">Keyword Geo-Maps</span>
            </div>
            <div className="bg-slate-50 p-3.5 rounded-xl border border-slate-200/80">
              <span className="text-xl font-black font-mono text-slate-900 block">
                {competitorCount}
              </span>
              <span className="text-[11px] font-semibold text-slate-500">Top Competitors</span>
            </div>
          </div>

          <button
            onClick={handleGeneratePlan}
            disabled={isGenerating}
            className="px-6 py-3 bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-300 text-white rounded-xl text-xs font-bold shadow-sm transition-all flex items-center justify-center space-x-2 mx-auto cursor-pointer"
          >
            <Sparkles className="w-4 h-4" />
            <span>{isGenerating ? 'Structuring site architecture...' : 'Create site plan'}</span>
          </button>
        </div>
      ) : (
        /* State 2: Generated Sitemap Tree */
        <div className="space-y-6">
          {/* Header Bar */}
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-xs flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
              <div className="flex items-center space-x-2 text-slate-900">
                <span className="p-2 bg-emerald-100 text-emerald-700 rounded-xl">
                  <FolderTree className="w-5 h-5" />
                </span>
                <h2 className="text-lg font-bold">
                  Site plan • {totalPages} pages — Writes with Gemini / Claude API
                </h2>
              </div>
              <p className="text-xs text-slate-500 mt-1">
                Structured local SEO hierarchy built to intercept Google 3-Pack and organic local queries for <strong className="text-slate-700">{businessName}</strong>.
              </p>
            </div>

            <div className="flex items-center space-x-3 self-start md:self-auto">
              <button
                onClick={() => onLaunchSiteBuilder && onLaunchSiteBuilder('/')}
                className="inline-flex items-center gap-1.5 px-4 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-xs font-bold shadow-xs transition-colors cursor-pointer"
              >
                <span>Build this site →</span>
                <ArrowRight className="w-4 h-4" />
              </button>
            </div>
          </div>

          {/* Group Columns (3 Pillars) */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            {/* Column 1: Main Pages */}
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-2xs space-y-3.5">
              <div className="flex items-center justify-between border-b border-slate-100 pb-2.5">
                <div className="flex items-center space-x-2">
                  <Building className="w-4 h-4 text-slate-700" />
                  <h3 className="text-xs font-bold uppercase tracking-wider text-slate-900">
                    Main Pages ({mainPages.length})
                  </h3>
                </div>
                <span className="text-[10px] font-mono text-slate-400">Core Architecture</span>
              </div>

              <div className="space-y-2">
                {mainPages.map((page) => (
                  <div
                    key={page.slug}
                    onClick={() => onLaunchSiteBuilder && onLaunchSiteBuilder(page.slug)}
                    className="p-3 bg-slate-50/70 hover:bg-emerald-50/50 rounded-xl border border-slate-200/70 hover:border-emerald-300 transition-colors cursor-pointer space-y-1"
                  >
                    <div className="flex items-center justify-between text-xs font-semibold text-slate-900">
                      <span>{page.title}</span>
                      <span className="text-[10px] font-mono text-emerald-700 bg-white px-1.5 py-0.5 rounded border border-slate-200">
                        {page.slug}
                      </span>
                    </div>
                    <p className="text-[11px] text-slate-500 leading-tight">
                      {page.desc}
                    </p>
                  </div>
                ))}
              </div>
            </div>

            {/* Column 2: Areas We Serve */}
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-2xs space-y-3.5">
              <div className="flex items-center justify-between border-b border-slate-100 pb-2.5">
                <div className="flex items-center space-x-2">
                  <MapPin className="w-4 h-4 text-emerald-600" />
                  <h3 className="text-xs font-bold uppercase tracking-wider text-slate-900">
                    Areas We Serve ({areaPages.length})
                  </h3>
                </div>
                <span className="text-[10px] font-mono text-emerald-700 bg-emerald-50 px-1.5 py-0.5 rounded border border-emerald-200">
                  Step 1 Extracted
                </span>
              </div>

              <div className="space-y-2">
                {areaPages.map((page) => (
                  <div
                    key={page.slug}
                    onClick={() => onLaunchSiteBuilder && onLaunchSiteBuilder(page.slug)}
                    className="p-3 bg-slate-50/70 hover:bg-emerald-50/50 rounded-xl border border-slate-200/70 hover:border-emerald-300 transition-colors cursor-pointer space-y-1"
                  >
                    <div className="flex items-center justify-between text-xs font-semibold text-slate-900">
                      <span>{page.title}</span>
                      <span className="text-[10px] font-mono text-emerald-700 bg-white px-1.5 py-0.5 rounded border border-slate-200">
                        {page.slug}
                      </span>
                    </div>
                    <p className="text-[11px] text-slate-500 leading-tight">
                      {page.desc}
                    </p>
                  </div>
                ))}
              </div>
            </div>

            {/* Column 3: Services */}
            <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-2xs space-y-3.5">
              <div className="flex items-center justify-between border-b border-slate-100 pb-2.5">
                <div className="flex items-center space-x-2">
                  <Target className="w-4 h-4 text-blue-600" />
                  <h3 className="text-xs font-bold uppercase tracking-wider text-slate-900">
                    Services ({servicePages.length})
                  </h3>
                </div>
                <span className="text-[10px] font-mono text-blue-700 bg-blue-50 px-1.5 py-0.5 rounded border border-blue-200">
                  Keyword Synced
                </span>
              </div>

              <div className="space-y-2">
                {servicePages.map((page) => (
                  <div
                    key={page.slug}
                    onClick={() => onLaunchSiteBuilder && onLaunchSiteBuilder(page.slug)}
                    className="p-3 bg-slate-50/70 hover:bg-emerald-50/50 rounded-xl border border-slate-200/70 hover:border-emerald-300 transition-colors cursor-pointer space-y-1"
                  >
                    <div className="flex items-center justify-between text-xs font-semibold text-slate-900">
                      <span>{page.title}</span>
                      <span className="text-[10px] font-mono text-emerald-700 bg-white px-1.5 py-0.5 rounded border border-slate-200">
                        {page.slug}
                      </span>
                    </div>
                    <p className="text-[11px] text-slate-500 leading-tight">
                      {page.desc}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
